module shift_register(
    input wire clk,
    input wire reset,
    input wire serial_in,
    output wire serial_out
    );

reg [31:0] shift_reg;

always @(posedge clk or posedge reset) begin
    if (reset) begin
        shift_reg <= 32'd0;
    end else begin
        shift_reg <= {shift_reg[30:0], serial_in};
    end
end

assign serial_out = shift_reg[31];

endmodule

