module moore_machine (
  input in1,
  input in2,
  input [1:0] state,
  output reg [1:0] next_state,
  output reg out);parameter S0=0, S1=1, S2=2, S3=3;

    always_comb begin
        case (state)
            S0: next_state = in1 ? S2 : S1;
            S1: next_state = in2 ? S3 : S0;
            S2: next_state = in1 ? S0 : S3;
            S3: next_state = in2 ? S1 : S2;
        endcase
    end

    always_comb begin
        case (state)
            S0: out = 0;
            S1: out = 1;
            S2: out = 0;
            S3: out = 1;
        endcase
    end

endmodule

