module top_module(
  input clk,
  input reset,
  input req_val,
  input [31:0] req_msg,
  output reg req_rdy,  // Changed to reg
  input resp_rdy,
  output reg resp_val,  // Changed to reg
  output reg [31:0] resp_msg  // Changed to reg
);reg [31:0] a;
  reg [31:0] b;
  reg [31:0] rem;
  reg [31:0] result_gcd; // Renamed to avoid conflict with output
  reg [1:0] state;

  always @(posedge clk) begin
    if (reset) begin
      state <= 0;
      req_rdy <= 0;
      resp_val <= 0;
      a <= 0;
      b <= 0;
      rem <= 0;
      result_gcd <= 0; // Changed to result_gcd
    end else begin
      case (state)
        0: begin // wait for request
          req_rdy <= 1;  // Set req_rdy to 1 when in this state
          if (req_val) begin
            state <= 1;
            a <= req_msg;
            req_rdy <= 0; // Ready goes low after receiving request
          end
        end
        1: begin // wait for second number
          if (req_val) begin
            state <= 2;
            b <= req_msg;
            req_rdy <= 0; // Ready goes low after receiving request
          end
        end
        2: begin // compute GCD
          rem <= a % b;
          if (rem == 0) begin
            result_gcd <= b;
            state <= 3;
          end else begin
            a <= b;
            b <= rem;
          end
        end
        3: begin // output result
          if (resp_rdy) begin
            resp_val <= 1;
            resp_msg <= result_gcd; // Using result_gcd here
            state <= 0;
          end else begin
            resp_val <= 0; // Resetting resp_val if not ready to send
          end
        end
      endcase
    end
  end

endmodule

