module top_module(
    input clk,
    input rst,
    output [7:0] tx_data,
    output reg new_tx_data,
    input tx_busy,
    input [7:0] rx_data,
    input new_rx_data
);localparam STATE_SIZE = 2;
localparam IDLE = 2'b00,
           PRINT_MESSAGE = 2'b01,
           WAIT_FOR_TX = 2'b10;

localparam MESSAGE_LEN = 14;

reg [STATE_SIZE-1:0] state_d, state_q;

reg [3:0] addr_d, addr_q;

// Define the message_rom module as a memory block with predefined messages
reg [7:0] message_rom [0:MESSAGE_LEN-1];

initial begin
    // Fill the message ROM with some example messages (optional)
    message_rom[0] = 8'h48; // 'H'
    message_rom[1] = 8'h65; // 'e'
    message_rom[2] = 8'h6C; // 'l'
    message_rom[3] = 8'h6C; // 'l'
    message_rom[4] = 8'h6F; // 'o'
    message_rom[5] = 8'h2C; // ','
    message_rom[6] = 8'h20; // ' '
    message_rom[7] = 8'h57; // 'W'
    message_rom[8] = 8'h6F; // 'o'
    message_rom[9] = 8'h72; // 'r'
    message_rom[10] = 8'h6C; // 'l'
    message_rom[11] = 8'h64; // 'd'
    message_rom[12] = 8'h21; // '!'
    message_rom[13] = 8'h00; // Null terminator
end

assign tx_data = message_rom[addr_q];

always @(*) begin
    state_d = state_q; // default values
    addr_d = addr_q;   // needed to prevent latches
    new_tx_data = 1'b0;

    case (state_q)
        IDLE: begin
            addr_d = 4'd0;
            if (new_rx_data) begin
                state_d = PRINT_MESSAGE;
            end
        end
        PRINT_MESSAGE: begin
            if (!tx_busy) begin
                new_tx_data = 1'b1;
                addr_d = addr_q + 1'b1;
                if (addr_q == MESSAGE_LEN-1) begin
                    state_d = WAIT_FOR_TX;
                end
            end
        end
        WAIT_FOR_TX: begin
            if (tx_busy == 1'b0) begin
                state_d = IDLE;
            end
        end
        default: state_d = IDLE;
    endcase
end

always @(posedge clk) begin
    if (rst) begin
        state_q <= IDLE;
        addr_q <= 4'd0;
    end else begin
        state_q <= state_d;
        addr_q <= addr_d;
    end
end

endmodule

