module top_module(
    // inputs
    address_a,
    address_b,
    byteena_a,
    clock0,
    clock1,
    clocken0,
    clocken1,
    data_a,
    data_b,
    wren_a,
    wren_b,
    // outputs
    q_a,
    q_b
);parameter WIDTH = 32;
    parameter DEPTH = 256;

    input [7:0] address_a;
    input [7:0] address_b;
    input [3:0] byteena_a;
    input clock0;
    input clock1;
    input clocken0;
    input clocken1;
    input [WIDTH-1:0] data_a;
    input [WIDTH-1:0] data_b;
    input wren_a;
    input wren_b;

    output reg [WIDTH-1:0] q_a;
    output reg [WIDTH-1:0] q_b;

    reg [WIDTH-1:0] ram [0:DEPTH-1];

    always @(posedge clock0) begin
        if (clocken0) begin
            if (wren_a) begin
                if (byteena_a[0]) ram[address_a][7:0] <= data_a[7:0];
                if (byteena_a[1]) ram[address_a][15:8] <= data_a[15:8];
                if (byteena_a[2]) ram[address_a][23:16] <= data_a[23:16];
                if (byteena_a[3]) ram[address_a][31:24] <= data_a[31:24];
            end
            q_a <= ram[address_a];
        end
    end

    always @(posedge clock1) begin
        if (clocken1) begin
            if (wren_b) begin
                ram[address_b] <= data_b;
            end
            q_b <= ram[address_b];
        end
    end

endmodule

