module top_module(
  input clk,
  input reset,
  input dtr,
  output reg tx
);parameter BAUD = 115200;

  localparam BITRATE = BAUD * 2;
  localparam FRAME = BITRATE * 11;
  localparam FRAME_WAIT = BITRATE * 4;

  reg [7:0] data;
  reg [3:0] state;
  reg [15:0] counter;

  always @(posedge clk, posedge reset) begin
    if (reset) begin
      tx <= 0;
      state <= 0;
      counter <= 0;
    end else begin
      case (state)
        0: begin // idle
          if (dtr) begin
            state <= 1;
            counter <= FRAME_WAIT;
          end
        end
        1: begin // start bit
          tx <= 0;
          state <= 2;
          counter <= BITRATE;
        end
        2: begin // data bits
          tx <= data[0];
          data <= {data[6:0], dtr};
          state <= state + 1;
          counter <= BITRATE;
        end
        9: begin // stop bit
          tx <= 1;
          state <= 0;
          counter <= BITRATE;
        end
        default: begin // wait for next bit
          tx <= 1;
          state <= state + 1;
          counter <= BITRATE;
        end
      endcase
    end
  end

  always @(posedge clk, posedge reset) begin
    if (reset) begin
      data <= 8'b0;
    end
  end

endmodule

