  // outputs
  output [RegLen:0] reg_out;
  // inouts
  // special inputs
  input clk;
  input reset;
  input flush;
  // inputs
  input [RegLen:0] reg_in;

  // internal vars
  reg [RegLen:0] reg_val;

  // assign vars

  // assign outputs
  assign reg_out = reg_val;

  // change the value of the register on every rising clock edge if the flush signal is low
  always @(posedge clk)
  begin
    if (flush == 1'b1)
    begin
