module top_module (
    input clk,
    input reset,
    input in,
    output reg out );typedef enum reg [2:0] {S0, S1, S2, S3, S4} state_t;
state_t state, next_state;

always @(posedge clk) begin
    if (reset)
        state <= S0;
    else
        state <= next_state;
end

always @(*) begin
    case (state)
        S0: next_state = in ? S1 : S0;
        S1: next_state = in ? S2 : S0;
        S2: next_state = in ? S2 : S3;
        S3: next_state = in ? S4 : S0;
        S4: next_state = in ? S2 : S0;
        default: next_state = S0;
    endcase
end

always @(posedge clk) begin
    if (reset)
        out <= 1'b0;
    else if (state == S4)
        out <= 1'b1;
    else
        out <= 1'b0;
end

endmodule

