    input RESETn,
    input BC_RELEASE_ISO,
    input SC_CLR_BUSY,
    input MBUS_CLR_BUSY,
    output reg BUS_BUSYn
);reg clr_busy_temp;

    always @ *
    begin
        if (BC_RELEASE_ISO == 1'b1)
            clr_busy_temp = 1'b0;
        else
            clr_busy_temp = MBUS_CLR_BUSY;
    end

